package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Stream;
import java.util.zip.ZipInputStream;
import org.jlinalg.sequence.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

/** Actual original LinkPeaks, background correlation and geometry controls, without R at test time. */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
public class SignacPeakLinksTest {
    @TempDir static Path root;
    private Map<String,Object> cases,original;
    private final AtomicInteger files=new AtomicInteger();
    private record Input(SignacPeakLinks.Sparse counts,SignacPeakLinks.Sparse expression,List<SignacFragments.Region> peaks,List<SignacPeakLinks.Gene> genes,SignacPeakLinks.Options options,SignacPeakLinks.Profile profile,List<SignacPeakLinks.Background> background,List<SignacPeakLinks.Link> links) { }
    @BeforeAll void fixture()throws Exception{byte[] raw;try(var in=getClass().getResourceAsStream("/org/jlinalg/sequence/signac-links/original-controls.zip")){assertNotNull(in);raw=in.readAllBytes();}assertEquals("6093f884a7ec14b0d1add18aa44c631557ab78435227c73e0c6ca72398792699",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw)));try(var zip=new ZipInputStream(new ByteArrayInputStream(raw))){java.util.zip.ZipEntry e;while((e=zip.getNextEntry())!=null){Path target=root.resolve(e.getName()).normalize();assertTrue(target.startsWith(root));Files.createDirectories(target.getParent());Files.write(target,zip.readAllBytes());}}cases=object(SimpleJson.parse(Files.readString(root.resolve("cases.json"),StandardCharsets.UTF_8)));original=object(SimpleJson.parse(Files.readString(root.resolve("original.json"),StandardCharsets.UTF_8)));}
    @TestFactory Stream<DynamicTest> fullOriginalResults(){List<DynamicTest> tests=new ArrayList<>();for(Object value:list(original.get("results"))){var record=object(value);var result=object(object(record.get("result")).get("value"));if(result.containsKey("error"))continue;for(boolean parsed:new boolean[]{false,true})tests.add(DynamicTest.dynamicTest(text(record,"profile")+"/"+text(record,"id")+"/parsed="+parsed,()->{Input in=input(record,parsed);var diagnostics=audit(in,in.background,in.links);assertEquals(in.background.size(),diagnostics.testedPairs());assertEquals(in.links.size(),diagnostics.retainedLinks());assertTrue(diagnostics.maximumCoefficientError()<=5e-11);assertTrue(diagnostics.maximumZError()<1e-6);assertTrue(diagnostics.maximumLogPError()<1e-6);}));}return tests.stream();}
    @TestFactory Stream<DynamicTest> alteredScientificEvidence(){List<DynamicTest> tests=new ArrayList<>();for(String mutation:List.of("candidate","background-coefficient","background-identity","pool","repeated-draw","reported-score","reported-range","missing-pair","extra-pair","missing-link"))tests.add(DynamicTest.dynamicTest(mutation,()->{Input in=baseline();List<SignacPeakLinks.Background> backgrounds=new ArrayList<>(in.background);List<SignacPeakLinks.Link> links=new ArrayList<>(in.links);var b=backgrounds.get(0);var l=links.get(0);List<String> peaks=new ArrayList<>(b.peaks()),pool=new ArrayList<>(b.pool());double[] coefficients=b.coefficients();double coefficient=b.coefficient();
        switch(mutation){case "candidate"->coefficient+=0.01;case "background-coefficient"->coefficients[0]+=0.01;case "background-identity"->peaks.set(0,pool.stream().filter(v->!peaks.contains(v)).findFirst().orElseThrow());case "pool"->pool.remove(0);case "repeated-draw"->peaks.set(0,peaks.get(1));case "reported-score"->links.set(0,new SignacPeakLinks.Link(l.chromosome(),l.start(),l.end(),l.gene(),l.peak(),l.coefficient()+0.01,l.zscore(),l.pvalue()));case "reported-range"->links.set(0,new SignacPeakLinks.Link(l.chromosome(),l.start()+1,l.end(),l.gene(),l.peak(),l.coefficient(),l.zscore(),l.pvalue()));case "missing-pair"->backgrounds.remove(0);case "extra-pair"->backgrounds.add(b);case "missing-link"->links.remove(0);default->throw new AssertionError();}
        if(!Set.of("missing-pair","extra-pair").contains(mutation))backgrounds.set(0,new SignacPeakLinks.Background(b.gene(),b.peak(),coefficient,peaks,coefficients,b.zscore(),b.pvalue(),b.retained(),pool));assertThrows(IOException.class,()->audit(in,backgrounds,links));}));return tests.stream();}
    @Test void signedUnicodeExpressionRoundTrip()throws Exception{List<String> cells=List.of("cell α","cell β","cell γ"),features=List.of("gene α","gene β");var matrix=new SignacPeakLinks.Sparse(features,cells,new int[]{0,2,3,4},new int[]{0,1,1,0},new double[]{-2,0,1.5,3});var copy=roundTrip(matrix);assertEquals(features,copy.features());assertEquals(cells,copy.cells());assertArrayEquals(matrix.pointers(),copy.pointers());assertArrayEquals(matrix.rows(),copy.rows());assertArrayEquals(matrix.values(),copy.values());}
    @Test void malformedExpressionIsRejected()throws Exception{Path features=root.resolve("bad-features.tsv"),cells=root.resolve("bad-cells.tsv");Files.writeString(features,"G\n");Files.writeString(cells,"A\nB\n");for(String data:List.of("%%MatrixMarket matrix array real general\n1 2 1\n1 1 2\n","%%MatrixMarket matrix coordinate real general\n1 2 2\n1 1 1\n1 1 2\n","%%MatrixMarket matrix coordinate real general\n1 2 1\n1 1 NaN\n","%%MatrixMarket matrix coordinate integer general\n1 2 1\n1 1 1.5\n","%%MatrixMarket matrix coordinate real general\n1 2 1\n1 3 1\n")){Path path=root.resolve("malformed-"+files.incrementAndGet());Files.writeString(path,data);assertThrows(IOException.class,()->SignacLinkIO.readExpression(path,features,cells,SignacLinkIO.Limits.defaults(),()->false));}}
    @Test void metadataOrderAndNonfiniteValuesFail()throws Exception{Path path=root.resolve("bad-meta.tsv");Files.writeString(path,"peak_id\tGC.percent\tsequence.length\tcount\nwrong\t50\t100\t\n");assertThrows(IOException.class,()->SignacLinkIO.metadata(path,List.of("peak"),SignacLinkIO.Limits.defaults(),()->false));assertThrows(IllegalArgumentException.class,()->new SignacLinkIO.Metadata(Double.NaN,1,null));}
    @Test void emptySparseRanksRetainSourceFailure(){assertThrows(IOException.class,()->SignacPeakLinks.correlation(new double[]{0,0,0},new boolean[]{false,false,false},new double[]{1,2,3},new boolean[]{true,true,true},SignacPeakLinks.Method.SPARSE_SPEARMAN,()->false));}
    @Test void analyticPearsonAndStorageMasks()throws Exception{assertEquals(-1,SignacPeakLinks.correlation(new double[]{1,2,3},new boolean[]{true,true,true},new double[]{3,2,1},new boolean[]{true,true,true},SignacPeakLinks.Method.PEARSON,()->false),1e-14);assertThrows(IllegalArgumentException.class,()->SignacPeakLinks.correlation(new double[]{1,0},new boolean[]{false,false},new double[]{1,2},new boolean[]{true,true},SignacPeakLinks.Method.PEARSON,()->false));}
    @Test void cancellationStopsActualAudit()throws Exception{Input in=baseline();AtomicInteger checks=new AtomicInteger();assertThrows(CancellationException.class,()->SignacPeakLinks.audit(in.counts,in.expression,in.peaks,in.genes,in.options,in.profile,in.background,in.links,()->checks.incrementAndGet()>30));assertTrue(checks.get()>30);}
    @Test void explicitWorkBoundFails()throws Exception{Input in=baseline();var o=in.options;var bounded=new SignacPeakLinks.Options(o.method(),o.distance(),o.minDistance(),o.minCells(),o.sample(),o.pCutoff(),o.scoreCutoff(),o.geneIds(),o.genesUse(),1);assertThrows(IOException.class,()->SignacPeakLinks.audit(in.counts,in.expression,in.peaks,in.genes,bounded,in.profile,in.background,in.links,()->false));}
    @Test void nonintegerPeaksAndCellPermutationFail()throws Exception{Input in=baseline();double[] values=in.counts.values();values[0]=1.5;var counts=new SignacPeakLinks.Sparse(in.counts.features(),in.counts.cells(),in.counts.pointers(),in.counts.rows(),values);assertThrows(IOException.class,()->SignacPeakLinks.audit(counts,in.expression,in.peaks,in.genes,in.options,in.profile,in.background,in.links,()->false));List<String> cells=new ArrayList<>(in.expression.cells());Collections.reverse(cells);var expression=new SignacPeakLinks.Sparse(in.expression.features(),cells,in.expression.pointers(),in.expression.rows(),in.expression.values());assertThrows(IOException.class,()->SignacPeakLinks.audit(in.counts,expression,in.peaks,in.genes,in.options,in.profile,in.background,in.links,()->false));}
    @Test void sourceTailAndHistoricalPrefixAreExplicit()throws Exception{assertEquals(0.5,SignacPeakLinks.sourceNormalTail(0));Input in=baseline();assertTrue(in.background.stream().filter(v->v.gene().equals("G1")).anyMatch(v->v.pool().stream().anyMatch(p->p.startsWith("chr10-"))));var record=list(original.get("results")).stream().map(SignacPeakLinksTest::object).filter(v->text(v,"profile").equals("1.14.0-source")&&text(v,"id").equals("pearson-6-1")).findFirst().orElseThrow();assertTrue(input(record,false).background.stream().filter(v->v.gene().equals("G1")).allMatch(v->v.pool().stream().noneMatch(p->p.startsWith("chr10-"))));}
    @Test void capturedAndInputArraysAreImmutable()throws Exception{Input in=baseline();double[] values=in.counts.values();values[0]=999;double[] background=in.background.get(0).coefficients();background[0]=999;assertNotEquals(999,in.counts.values()[0]);assertNotEquals(999,in.background.get(0).coefficients()[0]);assertEquals(in.links.size(),audit(in,in.background,in.links).retainedLinks());}
    @Test void originalAuditRngMatchesFullFunction(){for(Object value:list(original.get("results"))){var v=object(object(object(value).get("result")).get("value"));if(!v.containsKey("error"))assertEquals(v.get("seed_after"),object(v.get("audit")).get("seed_after"));}}
    private SignacPeakLinks.Diagnostics audit(Input in,List<SignacPeakLinks.Background> backgrounds,List<SignacPeakLinks.Link> links)throws IOException{return SignacPeakLinks.audit(in.counts,in.expression,in.peaks,in.genes,in.options,in.profile,backgrounds,links,()->false);}
    private Input baseline()throws Exception{var r=list(original.get("results")).stream().map(SignacPeakLinksTest::object).filter(v->text(v,"profile").equals("1.17.1-package")&&text(v,"id").equals("pearson-6-1")).findFirst().orElseThrow();return input(r,false);}
    private Input input(Map<String,Object> record,boolean parsed)throws Exception{
        var c=list(cases.get("cases")).stream().map(SignacPeakLinksTest::object).filter(v->text(v,"id").equals(text(record,"id"))).findFirst().orElseThrow();var d=object(object(cases.get("datasets")).get(c.get("dataset")));var result=object(object(record.get("result")).get("value"));List<String> cells=strings(d.get("cells"));List<SignacFragments.Region> peaks=new ArrayList<>();for(Object raw:list(d.get("peaks"))){var p=object(raw);peaks.add(new SignacFragments.Region(text(p,"chromosome"),integer(p,"start"),integer(p,"end")));}List<SignacPeakLinks.Gene> genes=new ArrayList<>();for(Object raw:list(d.get("genes"))){var g=object(raw);genes.add(new SignacPeakLinks.Gene(text(g,"chromosome"),integer(g,"start"),integer(g,"end"),text(g,"strand"),text(g,"gene_id"),text(g,"gene_name")));}
        SignacPeakLinks.Sparse counts=sparse(list(d.get("counts")),peaks.stream().map(SignacFragments.Region::name).toList(),cells,false),expression=sparse(list(d.get("expression")),genes.stream().map(g->bool(c,"gene_id")?g.id():g.name()).toList(),cells,Boolean.TRUE.equals(d.get("keep_stored_zeros")));if(parsed)expression=roundTrip(expression);
        var o=new SignacPeakLinks.Options(text(c,"method").equals("pearson")?SignacPeakLinks.Method.PEARSON:SignacPeakLinks.Method.SPARSE_SPEARMAN,integer(c,"distance"),c.get("min_distance")==null?null:integer(c,"min_distance"),integer(c,"min_cells"),integer(c,"n_sample"),number(c.get("pvalue_cutoff")),number(c.get("score_cutoff")),bool(c,"gene_id"),c.get("genes_use")==null?null:strings(c.get("genes_use")),2_000_000_000L);List<SignacPeakLinks.Background> backgrounds=new ArrayList<>();for(Object raw:array(object(result.get("audit")).get("pairs"))){var b=object(raw);backgrounds.add(new SignacPeakLinks.Background(text(b,"gene"),text(b,"peak"),number(b.get("coefficient")),strings(b.get("background")),array(b.get("background_coefficients")).stream().mapToDouble(SignacPeakLinksTest::number).toArray(),extended(b.get("zscore")),number(b.get("pvalue")),bool(b,"retained"),strings(b.get("pool"))));}List<SignacPeakLinks.Link> links=new ArrayList<>();for(Object raw:array(result.get("links"))){var l=object(raw);links.add(new SignacPeakLinks.Link(text(l,"seqnames"),integer(l,"start"),integer(l,"end"),text(l,"gene"),text(l,"peak"),number(l.get("score")),extended(l.get("zscore")),number(l.get("pvalue"))));}return new Input(counts,expression,peaks,genes,o,text(record,"profile").equals("1.17.1-package")?SignacPeakLinks.Profile.CURRENT_1_17_1:SignacPeakLinks.Profile.SOURCE_1_14_0,backgrounds,links);
    }
    private SignacPeakLinks.Sparse roundTrip(SignacPeakLinks.Sparse matrix)throws Exception{Path folder=root.resolve("expression-"+files.incrementAndGet());Files.createDirectory(folder);Files.writeString(folder.resolve("features.tsv"),String.join("\n",matrix.features())+"\n",StandardCharsets.UTF_8);Files.writeString(folder.resolve("cells.tsv"),String.join("\n",matrix.cells())+"\n",StandardCharsets.UTF_8);SignacLinkIO.writeExpression(matrix,folder.resolve("matrix.mtx"),()->false);return SignacLinkIO.readExpression(folder.resolve("matrix.mtx"),folder.resolve("features.tsv"),folder.resolve("cells.tsv"),SignacLinkIO.Limits.defaults(),()->false);}
    private static SignacPeakLinks.Sparse sparse(List<?> rows,List<String> features,List<String> cells,boolean stored){List<Integer> indices=new ArrayList<>();List<Double> values=new ArrayList<>();int[] p=new int[cells.size()+1];for(int cell=0;cell<cells.size();cell++){for(int row=0;row<rows.size();row++){double value=number(list(rows.get(row)).get(cell));if(stored||value!=0){indices.add(row);values.add(value);}}p[cell+1]=indices.size();}return new SignacPeakLinks.Sparse(features,cells,p,indices.stream().mapToInt(Integer::intValue).toArray(),values.stream().mapToDouble(Double::doubleValue).toArray());}
    private static Map<String,Object> object(Object value){Map<String,Object> result=new LinkedHashMap<>();for(var e:((Map<?,?>)value).entrySet())result.put((String)e.getKey(),e.getValue());return result;}
    private static List<?> list(Object value){return (List<?>)value;}
    private static List<?> array(Object value){return value==null?List.of():value instanceof List<?> l?l:List.of(value);}
    private static List<String> strings(Object value){return array(value).stream().map(String.class::cast).toList();}
    private static String text(Map<String,Object> value,String key){return (String)value.get(key);}
    private static int integer(Map<String,Object> value,String key){return ((Number)value.get(key)).intValue();}
    private static boolean bool(Map<String,Object> value,String key){return (Boolean)value.get(key);}
    private static double number(Object value){return ((Number)value).doubleValue();}
    private static double extended(Object value){return value instanceof Number n?n.doubleValue():value.equals("Inf")?Double.POSITIVE_INFINITY:value.equals("-Inf")?Double.NEGATIVE_INFINITY:Double.NaN;}
}
